    # Initialize the grid with zeros
    grid = [[0] * n for _ in range(n)]

    # Process each command
    for command in commands:
        parts = command.split()
        action = parts[0]

        if action == "SET":
            x, y, value = int(parts[1]), int(parts[2]), int(parts[3])
            grid[x][y] = value

        elif action == "ADD":
            x, y, value = int(parts[1]), int(parts[2]), int(parts[3])
            grid[x][y] += value

        elif action == "MULTIPLY":
            x, y, value = int(parts[1]), int(parts[2]), int(parts[3])
            grid[x][y] *= value

