def F(n, commands):
    def rotate_left(arr, d):
        return arr[d:] + arr[:d]

    def rotate_right(arr, d):
        return arr[-d:] + arr[:-d]

    def reverse(arr, start, end):
        while start < end:
            arr[start], arr[end] = arr[end], arr[start]
            start += 1
            end -= 1

    results = []
    for command in commands:
        parts = command.split()
        if parts[0] == "rotate":
            direction = parts[1]
            steps = int(parts[2])
            if direction == "left":
                results.append(rotate_left(n, steps))
            elif direction == "right":
                results.append(rotate_right(n, steps))
        elif parts[0] == "reverse":
            start = int(parts[1])
            end = int(parts[2])
            reverse(n, start, end)
            results.append(n[:])

    return results

