def F(n, m, k, roads, queries):
    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            parent[i] = find(parent, parent[i])
            return parent[i]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)

        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    for road in roads:
        u, v, w = road
        union(parent, rank, u, v)

    results = []
    for query in queries:
        x, y = query
        if find(parent, x) == find(parent, y):
            results.append("YES")
        else:
            results.append("NO")

    return results

